From 4a12e5df03b15a514cde08133922f5e10b0f5215 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:28:37 +0100
Subject: [PATCH] kded: Unmute a muted default device with the mute shortcut

Muting a device in the applet and then middle-clicking the tray icon or
pressing the mute key enabled the global mute on top, and turning it off
left the device muted. Now the toggle first unmutes the default device.

BUG: 527141
---
 applet/main.qml                    | 2 +-
 src/kded/audioshortcutsservice.cpp | 9 +++++++++
 2 files changed, 10 insertions(+), 1 deletion(-)

diff --git a/applet/main.qml b/applet/main.qml
index 1e44cded..c53a3b00 100644
--- a/applet/main.qml
+++ b/applet/main.qml
@@ -104,7 +104,7 @@ PlasmoidItem {
         }

         if (paSinkFilterModel.count > 0) {
-            lines.push(main.globalMuteSinks ? i18n("Middle-click to unmute")
+            lines.push(main.globalMuteSinks || (PreferredDevice.sink && PreferredDevice.sink.muted) ? i18n("Middle-click to unmute")
                                     : i18n("Middle-click to mute all audio"));
             lines.push(i18n("Scroll to adjust volume"));
         } else {
diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..598c1503 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -169,8 +169,13 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
     muteAction->setText(i18n("Mute"));
     muteAction->setShortcut(Qt::Key_VolumeMute);
     connect(muteAction, &QAction::triggered, this, [this]() {
+        auto sink = m_preferredDevice.sink();
         if (m_globalConfig->globalMuteSinks()) {
             disableGlobalSinkMute();
+        } else if (sink && sink->isMuted()) {
+            sink->setMuted(false);
+            showMute(volumePercent(sink->volume()));
+            playFeedback(-1);
         } else {
             enableGlobalSinkMute();
         }
@@ -182,8 +187,12 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
     muteMicAction->setText(i18n("Mute Microphone"));
     muteMicAction->setShortcuts({Qt::Key_MicMute, Qt::MetaModifier | Qt::Key_VolumeMute});
     connect(muteMicAction, &QAction::triggered, this, [this]() {
+        auto source = m_preferredDevice.source();
         if (m_globalConfig->globalMuteSources()) {
             disableGlobalSourceMute();
+        } else if (source && source->isMuted()) {
+            source->setMuted(false);
+            showMicMute(volumePercent(source->volume()));
         } else {
             enableGlobalSourceMute();
         }
